以下のように、再帰下降法で演算子の優先順位と括弧、単項の `+` / `-` を処理できます。`eval()` は使用していません。

```python
import re


_TOKEN_RE = re.compile(r"\s*(\d+(?:\.\d*)?|\.\d+|[()+\-*/])")


def eval_expression(expr):
    """
    +, -, *, /、括弧、負の数に対応した式の評価関数。
    例:
        eval_expression("3 + 4 * (2 - 1)")  # 7
    """
    if not isinstance(expr, str):
        raise TypeError("expr must be a string")

    text = expr.strip()
    if not text:
        raise ValueError("empty expression")

    # トークン化
    tokens = []
    pos = 0

    while pos < len(text):
        match = _TOKEN_RE.match(text, pos)
        if match is None:
            raise ValueError(f"invalid character at position {pos}")

        tokens.append(match.group(1))
        pos = match.end()

    index = 0

    def current():
        return tokens[index] if index < len(tokens) else None

    def consume(expected=None):
        nonlocal index

        token = current()
        if token is None:
            raise ValueError("unexpected end of expression")

        if expected is not None and token != expected:
            raise ValueError(f"expected {expected!r}, got {token!r}")

        index += 1
        return token

    def parse_expression():
        # 加算・減算
        value = parse_term()

        while current() in ("+", "-"):
            operator = consume()
            right = parse_term()

            if operator == "+":
                value += right
            else:
                value -= right

        return value

    def parse_term():
        # 乗算・除算
        value = parse_unary()

        while current() in ("*", "/"):
            operator = consume()
            right = parse_unary()

            if operator == "*":
                value *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                value /= right

        return value

    def parse_unary():
        # 単項の + / -
        if current() == "+":
            consume("+")
            return parse_unary()

        if current() == "-":
            consume("-")
            return -parse_unary()

        return parse_primary()

    def parse_primary():
        token = current()

        if token == "(":
            consume("(")
            value = parse_expression()
            consume(")")
            return value

        if token is None:
            raise ValueError("unexpected end of expression")

        if token in ("+", "-", "*", "/", ")"):
            raise ValueError(f"unexpected token: {token!r}")

        consume()

        # 整数は int、小数は float として扱う
        return float(token) if "." in token else int(token)

    result = parse_expression()

    if current() is not None:
        raise ValueError(f"unexpected token: {current()!r}")

    return result
```

使用例:

```python
print(eval_expression("3 + 4 * (2 - 1)"))  # 7
print(eval_expression("-2 * 3 + 10"))      # 4
print(eval_expression("2 * -(3 + 4)"))      # -14
print(eval_expression("10 / 2"))            # 5.0

eval_expression("1 / 0")  # ZeroDivisionError
```

